mapper.select:
SELECT DISTINCT B.FINPROD_ID id, B.FINPROD_NAME text, B.FINPROD_MARKET_ID object FROM TRD_FIN_PRODUCT_DEAL_TOTAL A left join FIN_PRODUCT B on A.FINPROD_ID = B.FINPROD_ID
(B.P_FINPROD_ID is null or B.P_FINPROD_ID = '')
and ( B.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND B.FINPROD_TYPE2 = #{FINPROD_TYPE}
AND B.PROFIT_TYPE = #{PROFIT_TYPE,jdbcType=VARCHAR}

select distinct A.PORTFOLIO_ID as portfolioId, C.PROFIT_TYPE as profitType, C.FINPROD_ID as finprodId, C.FINPROD_MARKET_ID as marketId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, fpa.SALE_DEPARTMENT as saleDepartment, fpa.DEAL_MODE as dealMode, A.TRADE_DATE as confirmDate, C.CCY as ccy, C.VDATE as prodVdate, fpa.IS_CYCLE as isCycle, fpa.IS_LAY as isLay, sum(decode(A.PS, #{JYFX_CPRG}, NVL(A.TRADE_AMT,0), #{JYFX_CPSG}, NVL(A.TRADE_AMT,0), 0)) as tdyBuyMoney, sum(decode(A.PS, #{JYFX_CPRG}, NVL(A.SHARE_AMT,0), #{JYFX_CPSG}, NVL(A.SHARE_AMT,0), 0)) as tdyBuyQty, sum(decode(A.PS, #{JYFX_CPSH}, NVL(A.TRADE_AMT,0), #{JYFX_CPDQ}, NVL(A.TRADE_AMT,0), #{JYFX_CPTQZZ}, NVL(A.TRADE_AMT,0), #{JYFX_CPWYSH}, NVL(A.TRADE_AMT,0), #{JYFX_CPTQSH},NVL(A.TRADE_AMT,0), 0)) as tdyRedMoney, sum(decode(A.PS, #{JYFX_CPSH}, NVL(A.SHARE_AMT,0), #{JYFX_CPDQ}, NVL(A.SHARE_AMT,0), #{JYFX_CPTQZZ}, NVL(A.SHARE_AMT,0), #{JYFX_CPWYSH}, NVL(A.SHARE_AMT,0), #{JYFX_CPTQSH},NVL(A.SHARE_AMT,0), 0)) as tdyRedQty, sum(NVL(A.INT_AMT, 0)) as tdyCarriedInterest, sum(decode(A.PS, #{JYFX_CPHLZT}, NVL(A.TRADE_AMT,0), 0)) as tdyCarriedMoney, sum(decode(A.PS, #{JYFX_CPHLZT}, NVL(A.SHARE_AMT,0), 0)) as tdyCarriedQty, sum(decode(A.PS, #{JYFX_FEQZ}, NVL(A.TRADE_AMT,0), 0)) as tdyForceIncreaseMoney, sum(decode(A.PS, #{JYFX_FEQZ}, NVL(A.SHARE_AMT,0), 0)) as tdyForceIncreaseQty, sum(decode(A.PS, #{JYFX_FEQJ}, NVL(A.TRADE_AMT,0), 0)) as tdyForceReduceMoney, sum(decode(A.PS, #{JYFX_FEQJ}, NVL(A.SHARE_AMT,0), 0)) as tdyForceReduceQty
from TRD_FIN_PRODUCT_DEAL_TOTAL A inner join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID and C.PROFIT_TYPE = #{PROFIT_TYPE_SY} left join FIN_PRODUCT_ADD fpa on C.FINPROD_ID = fpa.FINPROD_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join PA_FIN_PRODUCT PFP on C.FINPROD_ID = PFP.FINPROD_ID where C.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
and A.PS not in (#{JYFX_CPCQDJ},#{JYFX_CPFF},#{JYFX_SFJN})
and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N}
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND fpa.DEAL_MODE = #{dealMode}
AND A.SETTLE_DATE >= to_date(#{cashDateBegin}, 'yyyy-MM-dd')
AND A.SETTLE_DATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
AND A.TRADE_DATE >= to_date(#{confirmDateBegin}, 'yyyy-MM-dd')
AND A.TRADE_DATE <= to_date(#{confirmDateEnd}, 'yyyy-MM-dd')
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PS = #{dealType}
AND C.CCY = #{ccy}
AND fpa.PROD_MANAGER IN
#{item}
group by A.PORTFOLIO_ID, C.PROFIT_TYPE,C.FINPROD_ID, C.FINPROD_MARKET_ID, A.PROD_ID, A.TRADE_DATE, fpa.SALE_DEPARTMENT, C.CCY, C.VDATE, fpa.IS_LAY, fpa.IS_CYCLE, fpa.DEAL_MODE, A.SETTLE_DATE
union all
select distinct A.PORTFOLIO_ID as portfolioId, C.PROFIT_TYPE as profitType, C.FINPROD_ID as finprodId, C.FINPROD_MARKET_ID as marketId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, fpa.SALE_DEPARTMENT as saleDepartment, fpa.DEAL_MODE as dealMode, A.TRADE_DATE as confirmDate, C.CCY as ccy, C.VDATE as prodVdate, fpa.IS_CYCLE as isCycle, fpa.IS_LAY as isLay, sum(decode(A.PS, #{JYFX_CPRG}, A.TRADE_AMT, #{JYFX_CPSG}, A.TRADE_AMT, 0)) as tdyBuyMoney, sum(decode(A.PS, #{JYFX_CPRG}, A.SHARE_AMT, #{JYFX_CPSG}, A.SHARE_AMT, 0)) as tdyBuyQty, sum(decode(A.PS, #{JYFX_CPSH}, A.TRADE_AMT, #{JYFX_CPDQ}, A.TRADE_AMT, #{JYFX_CPTQZZ}, A.TRADE_AMT, #{JYFX_CPWYSH}, A.TRADE_AMT, #{JYFX_CPTQSH}, A.TRADE_AMT, 0)) as tdyRedMoney, sum(decode(A.PS, #{JYFX_CPSH}, A.SHARE_AMT, #{JYFX_CPDQ}, A.SHARE_AMT, #{JYFX_CPTQZZ}, A.SHARE_AMT, #{JYFX_CPWYSH}, A.SHARE_AMT, #{JYFX_CPTQSH}, A.SHARE_AMT, 0)) as tdyRedQty, sum(decode(A.PS, #{JYFX_CPXJFH}, A.TRADE_AMT, 0)) as tdyCarriedInterest, sum(decode(A.PS, #{JYFX_CPHLZT}, A.TRADE_AMT, 0)) as tdyCarriedMoney, sum(decode(A.PS, #{JYFX_CPHLZT}, A.SHARE_AMT, 0)) as tdyCarriedQty, sum(decode(A.PS, #{JYFX_FEQZ}, A.TRADE_AMT, 0)) as tdyForceIncreaseMoney, sum(decode(A.PS, #{JYFX_FEQZ}, A.SHARE_AMT, 0)) as tdyForceIncreaseQty, sum(decode(A.PS, #{JYFX_FEQJ}, A.TRADE_AMT, 0)) as tdyForceReduceMoney, sum(decode(A.PS, #{JYFX_FEQJ}, A.SHARE_AMT, 0)) as tdyForceReduceQty
from TRD_FIN_PRODUCT_DEAL_TOTAL A inner join FIN_PRODUCT C on A.FINPROD_ID = C.FINPROD_ID and C.PROFIT_TYPE <> #{PROFIT_TYPE_SY} left join FIN_PRODUCT_ADD fpa on C.FINPROD_ID = fpa.FINPROD_ID left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID left join PA_FIN_PRODUCT PFP on C.FINPROD_ID = PFP.FINPROD_ID where C.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
and A.PS not in (#{JYFX_CPCQDJ},#{JYFX_CPFF},#{JYFX_SFJN})
and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N}
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND fpa.DEAL_MODE = #{dealMode}
AND A.SETTLE_DATE >= to_date(#{cashDateBegin}, 'yyyy-MM-dd')
AND A.SETTLE_DATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
AND A.TRADE_DATE >= to_date(#{confirmDateBegin}, 'yyyy-MM-dd')
AND A.TRADE_DATE <= to_date(#{confirmDateEnd}, 'yyyy-MM-dd')
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PS = #{dealType}
AND fpa.PROD_MANAGER IN
#{item}
AND C.CCY = #{ccy}
group by A.PORTFOLIO_ID, C.PROFIT_TYPE,C.FINPROD_ID, C.FINPROD_MARKET_ID, A.PROD_ID, A.TRADE_DATE, fpa.SALE_DEPARTMENT, C.CCY, C.VDATE, fpa.IS_LAY, fpa.IS_CYCLE, fpa.DEAL_MODE, A.SETTLE_DATE
order by portfolioId, finprodId, prodId, cashDate

SELECT UNIT_CPRICE from TRD_FIN_PRODUCT_DEAL_TOTAL
where FINPROD_ID = #{finprodid}
and TRD_FIN_PRODUCT_DEAL_TOTAL.TRADE_DATE = #{confirmDate}

and rownum = 1

select A.PORTFOLIO_ID as portfolioId, A.FINPROD_ID as finprodId, A.PROD_ID as prodId, A.SETTLE_DATE as cashDate, A.PS as ps, A.SHARE_AMT as shareAmout, B.THEORY_PRIN as mPrin from TRD_FIN_PRODUCT_DEAL_TOTAL A left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL B on A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID where A.FINPROD_TYPE2 in( #{FINPROD_TYPE2_LCCP},#{FINPROD_TYPE2_LCZCP}) and A.TRADE_STATUS = #{TRADE_STATUS_CS} and A.IS_CANCEL = #{YES_NO_N} AND nvl(A.P_TRADE_ID, 'null') = 'null' /*add by zhangweiqi 2019-3-27 过滤撤销记录*/
AND A.PORTFOLIO_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND A.FINPROD_ID IN
#{item}
AND A.SETTLE_DATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
order by A.PORTFOLIO_ID, A.FINPROD_ID, A.PROD_ID, A.TRADE_DATE

select A.FINPROD_ID as finprodId, A.EFF_DATE as effDate, A.YIELD as yield, B.P_FINPROD_ID as pFinprodId from FIN_CASH_CALC_RULE A inner join FIN_PRODUCT B on A.FINPROD_ID = B.FINPROD_ID
inner join FIN_CASH_INFO C on A.CASH_ID = C.CASH_ID
where
A.FINPROD_TYPE2 in ( #{FINPROD_TYPE2_LCCP}, #{FINPROD_TYPE2_LCCPFD})
AND A.EFF_DATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
AND C.CASH_TYPE_1 = #{CASH_TYPE_1_LX} AND C.CASH_TYPE_2 = #{CASH_TYPE_2_LX}
AND A.FINPROD_ID in ( select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE = #{PROFIT_TYPE_SY} and (P_FINPROD_ID is null or P_FINPROD_ID = '')
AND FINPROD_ID IN
#{item}
union all select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE = #{PROFIT_TYPE_SY}
and (P_FINPROD_ID is not null or P_FINPROD_ID != '')
AND P_FINPROD_ID IN
#{item}
) order by B.P_FINPROD_ID, A.FINPROD_ID, A.EFF_DATE

select B.FINPROD_ID as finprodId, A.CDATE as cdate, decode(B.PROFIT_TYPE,#{PROFIT_TYPE_SY},A.TDY_YIELD,A.TDY_UNIT_VALUE) tdyYield from Bok_Position_Prd A LEFT JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID
1=1
AND A.CDATE >= to_date(#{cashDateBeginEarly}, 'yyyy-MM-dd')
AND A.CDATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
AND B.PROFIT_TYPE != #{PROFIT_TYPE_SY}
AND B.FINPROD_MARKET_ID IN
#{item}
AND B.FINPROD_ID IN
#{item}
order by B.FINPROD_ID, A.CDATE

select A.FINPROD_ID as finprodId, A.VAL_DATE as valDate, A.VALUATION as valuation from FIN_PRODUCT_VALUATION A
A.FINPROD_TYPE2 = #{FINPROD_TYPE2_LCCP}
AND A.VAL_DATE >= to_date(#{cashDateBeginEarly}, 'yyyy-MM-dd')
AND A.VAL_DATE <= to_date(#{cashDateEnd}, 'yyyy-MM-dd')
AND A.FINPROD_ID in ( select FINPROD_ID from FIN_PRODUCT where PROFIT_TYPE != #{PROFIT_TYPE_SY}
AND FINPROD_MARKET_ID IN
#{item}
AND FINPROD_ID IN
#{item}
)
order by A.FINPROD_ID, A.VAL_DATE

select A.FINPROD_MARKET_ID as prodId, A.FINPROD_ID as finProdId, B.SALE_DEPARTMENT as saleDept, B.DEAL_MODE as type from FIN_PRODUCT A left join FIN_PRODUCT_ADD B on A.FINPROD_ID = B.FINPROD_ID
where B.OPERATION_TYPE = #{ISSUE_MODE_01}
AND B.DEAL_MODE IN
#{item}
and A.MDATE >= #{platDate,jdbcType=DATE}

select UNIT_CPRICE, FINPROD_ID, TOTLE_TRADE_ID from TRD_PRODUCT_DEAL where 1=1
AND TOTLE_TRADE_ID IN
#{item, jdbcType = VARCHAR}
AND IS_CANCEL = #{YES_NO_N, jdbcType=VARCHAR}
